package mn.suld.api.map;

import java.util.HashMap;
import java.util.Map;

/**
 * The pack's 5 x 7 pixel font (Mongolian Cyrillic and Latin capitals, digits, a few signs), for text drawn into map
 * pixels: the minimap's coordinates and the area's name. Generated by tools/map/gen_pixel_font.py from
 * tools/pack/pixelfont.py; do not edit by hand. Lower case is drawn as upper case; a letter the font lacks is skipped.
 */
public final class PixelFont {

    public static final int HEIGHT = 7, SPACE = 3;

    /** A glyph: its width and one bit mask per row, bit 0 the leftmost pixel. */
    record Glyph(int width, int[] rows) {
    }

    private static final Map<Character, Glyph> GLYPHS = new HashMap<>();

    private static void put(char c, int width, int... rows) {
        GLYPHS.put(c, new Glyph(width, rows));
    }

    static {
        put('!', 1, 1, 1, 1, 1, 1, 0, 1);
        put('"', 3, 5, 5, 0, 0, 0, 0, 0);
        put('#', 5, 10, 31, 10, 10, 31, 10, 0);
        put('%', 5, 19, 11, 4, 4, 2, 25, 25);
        put('&', 5, 6, 9, 6, 21, 9, 9, 22);
        put('\'', 1, 1, 1, 0, 0, 0, 0, 0);
        put('(', 2, 2, 1, 1, 1, 1, 1, 2);
        put(')', 2, 1, 2, 2, 2, 2, 2, 1);
        put('+', 5, 0, 4, 4, 31, 4, 4, 0);
        put(',', 2, 0, 0, 0, 0, 0, 2, 1);
        put('-', 5, 0, 0, 0, 15, 0, 0, 0);
        put('.', 1, 0, 0, 0, 0, 0, 0, 1);
        put('/', 5, 16, 8, 8, 4, 2, 2, 1);
        put('0', 5, 14, 17, 25, 21, 19, 17, 14);
        put('1', 5, 4, 6, 4, 4, 4, 4, 14);
        put('2', 5, 14, 17, 16, 8, 4, 2, 31);
        put('3', 5, 14, 17, 16, 12, 16, 17, 14);
        put('4', 5, 8, 12, 10, 9, 31, 8, 8);
        put('5', 5, 31, 1, 15, 16, 16, 17, 14);
        put('6', 5, 14, 1, 1, 15, 17, 17, 14);
        put('7', 5, 31, 16, 8, 4, 2, 2, 2);
        put('8', 5, 14, 17, 17, 14, 17, 17, 14);
        put('9', 5, 14, 17, 17, 30, 16, 16, 14);
        put(':', 1, 0, 1, 0, 0, 0, 1, 0);
        put(';', 2, 0, 2, 0, 0, 2, 1, 0);
        put('<', 4, 8, 4, 2, 1, 2, 4, 8);
        put('=', 5, 0, 0, 31, 0, 31, 0, 0);
        put('>', 4, 1, 2, 4, 8, 4, 2, 1);
        put('?', 5, 14, 17, 16, 8, 4, 0, 4);
        put('A', 5, 14, 17, 17, 31, 17, 17, 17);
        put('B', 5, 15, 17, 17, 15, 17, 17, 15);
        put('C', 5, 14, 17, 1, 1, 1, 17, 14);
        put('D', 5, 15, 17, 17, 17, 17, 17, 15);
        put('E', 5, 31, 1, 1, 15, 1, 1, 31);
        put('F', 5, 31, 1, 1, 15, 1, 1, 1);
        put('G', 5, 14, 17, 1, 29, 17, 17, 14);
        put('H', 5, 17, 17, 17, 31, 17, 17, 17);
        put('I', 3, 7, 2, 2, 2, 2, 2, 7);
        put('J', 5, 28, 8, 8, 8, 8, 9, 6);
        put('K', 5, 17, 9, 5, 3, 5, 9, 17);
        put('L', 5, 1, 1, 1, 1, 1, 1, 31);
        put('M', 5, 17, 27, 21, 21, 17, 17, 17);
        put('N', 5, 17, 19, 21, 25, 17, 17, 17);
        put('O', 5, 14, 17, 17, 17, 17, 17, 14);
        put('P', 5, 15, 17, 17, 15, 1, 1, 1);
        put('Q', 5, 14, 17, 17, 17, 21, 9, 22);
        put('R', 5, 15, 17, 17, 15, 5, 9, 17);
        put('S', 5, 30, 1, 1, 14, 16, 16, 15);
        put('T', 5, 31, 4, 4, 4, 4, 4, 4);
        put('U', 5, 17, 17, 17, 17, 17, 17, 14);
        put('V', 5, 17, 17, 17, 17, 17, 10, 4);
        put('W', 5, 17, 17, 17, 21, 21, 27, 17);
        put('X', 5, 17, 17, 10, 4, 10, 17, 17);
        put('Y', 5, 17, 17, 10, 4, 4, 4, 4);
        put('Z', 5, 31, 16, 8, 4, 2, 1, 31);
        put('_', 5, 0, 0, 0, 0, 0, 0, 31);
        put('·', 1, 0, 0, 0, 1, 0, 0, 0);
        put('Ü', 5, 21, 0, 17, 17, 17, 17, 14);
        put('Ё', 5, 10, 31, 1, 15, 1, 1, 31);
        put('А', 5, 14, 17, 17, 31, 17, 17, 17);
        put('Б', 5, 31, 1, 1, 15, 17, 17, 15);
        put('В', 5, 15, 17, 17, 15, 17, 17, 15);
        put('Г', 5, 31, 1, 1, 1, 1, 1, 1);
        put('Д', 5, 14, 10, 10, 10, 10, 31, 17);
        put('Е', 5, 31, 1, 1, 15, 1, 1, 31);
        put('Ж', 5, 21, 21, 14, 4, 14, 21, 21);
        put('З', 5, 15, 16, 16, 14, 16, 16, 15);
        put('И', 5, 17, 17, 25, 21, 19, 17, 17);
        put('Й', 5, 10, 17, 25, 21, 19, 17, 17);
        put('К', 5, 17, 9, 5, 3, 5, 9, 17);
        put('Л', 5, 28, 18, 18, 18, 18, 18, 17);
        put('М', 5, 17, 27, 21, 21, 17, 17, 17);
        put('Н', 5, 17, 17, 17, 31, 17, 17, 17);
        put('О', 5, 14, 17, 17, 17, 17, 17, 14);
        put('П', 5, 31, 17, 17, 17, 17, 17, 17);
        put('Р', 5, 15, 17, 17, 15, 1, 1, 1);
        put('С', 5, 14, 17, 1, 1, 1, 17, 14);
        put('Т', 5, 31, 4, 4, 4, 4, 4, 4);
        put('У', 5, 17, 17, 17, 30, 16, 17, 14);
        put('Ф', 5, 4, 14, 21, 21, 14, 4, 4);
        put('Х', 5, 17, 17, 10, 4, 10, 17, 17);
        put('Ц', 5, 9, 9, 9, 9, 9, 31, 16);
        put('Ч', 5, 17, 17, 17, 30, 16, 16, 16);
        put('Ш', 5, 21, 21, 21, 21, 21, 21, 31);
        put('Щ', 5, 21, 21, 21, 21, 21, 21, 31);
        put('Ъ', 5, 1, 1, 1, 15, 17, 17, 15);
        put('Ы', 5, 17, 17, 17, 23, 25, 25, 23);
        put('Ь', 5, 1, 1, 1, 15, 17, 17, 15);
        put('Э', 5, 14, 17, 16, 30, 16, 17, 14);
        put('Ю', 5, 9, 21, 21, 23, 21, 21, 9);
        put('Я', 5, 30, 17, 17, 30, 20, 18, 17);
        put('Ү', 5, 17, 17, 10, 4, 4, 4, 4);
        put('Ө', 5, 14, 17, 17, 31, 17, 17, 14);
        put('—', 5, 0, 0, 0, 31, 0, 0, 0);
        put('◆', 5, 4, 14, 31, 31, 31, 14, 4);
        put('★', 5, 4, 4, 31, 14, 10, 17, 0);
        put('♥', 5, 0, 10, 31, 31, 14, 4, 0);
        put('⚔', 5, 4, 4, 4, 4, 31, 4, 14);
        put('✔', 5, 0, 16, 24, 13, 7, 2, 0);
        put('✖', 5, 0, 17, 10, 4, 10, 17, 0);
        put('✦', 5, 4, 4, 14, 31, 14, 4, 4);
        put('❄', 5, 4, 21, 14, 31, 14, 21, 4);
        put('➜', 5, 0, 4, 8, 31, 8, 4, 0);
    }

    private PixelFont() {
    }

    static Glyph glyph(char c) {
        Glyph g = GLYPHS.get(c);
        return g != null ? g : GLYPHS.get(Character.toUpperCase(c));
    }

    /** The width of {@code text} in pixels (one pixel between letters). */
    public static int width(String text) {
        int w = 0;
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (c == ' ') {
                w += SPACE + 1;
                continue;
            }
            Glyph g = glyph(c);
            if (g != null) w += g.width() + 1;
        }
        return Math.max(0, w - 1);
    }

    /** Draws {@code text} into a 128-wide map image with its top-left at (x, y); returns the x after it. */
    public static int draw(byte[] image, int x, int y, String text, byte colour) {
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (c == ' ') {
                x += SPACE + 1;
                continue;
            }
            Glyph g = glyph(c);
            if (g == null) continue;
            for (int r = 0; r < HEIGHT; r++) {
                for (int b = 0; b < g.width(); b++) {
                    if ((g.rows()[r] >> b & 1) == 0) continue;
                    int px = x + b, py = y + r;
                    if (px >= 0 && px < 128 && py >= 0 && py < 128) image[py * 128 + px] = colour;
                }
            }
            x += g.width() + 1;
        }
        return x;
    }
}
